int old_dir_fd, new_dir_fd;
const char *src = "original_file";
const char *dst = "hard_link_file";

// 1. Linking relative to the Current Working Directory (CWD)
int ret1 = linkat(AT_FDCWD, src,
                  AT_FDCWD, dst, 0);

// 2. Linking using explicit directory file descriptors
//    (oldpath and newpath are relative to the FDs)
old_dir_fd = open("SourceDir", O_RDONLY | O_DIRECTORY);
new_dir_fd = open("DestDir", O_RDONLY | O_DIRECTORY);

if (old_dir_fd > 0 && new_dir_fd > 0) {
    int ret2 = linkat(old_dir_fd, src,
                      new_dir_fd, dst, 0);
    close(old_dir_fd);
    close(new_dir_fd);
}
